/* Office mobile adapter. Computer/app/session state is a local interaction simulation. */
(()=>{
 'use strict';
 const L=(zh,en)=>document.documentElement.lang==='en'?en:zh;
 const state={owner:'',devices:{},treeOpen:{},capture:'desktop',app:'vscode',thread:'plan',origin:'detail',nativeOrigin:'office-ai',nativeContext:null,floatOpen:false,demo:'all',guideOpen:false,previewExpanded:true,previewKind:'ai',speechStatus:'idle',previewTab:0,landscape:false,zoom:1,captureOpen:false,nativeHistory:false,notice:''};
 const pendingReplies=new Map();let replySequence=0,speech=null;
 const apps=[{id:'vscode',name:'VS Code',icon:'terminal'},{id:'claude',name:'Claude',icon:'terminal'},{id:'workbuddy',name:'WorkBuddy',icon:'grid'},{id:'browser',name:'浏览器',en:'Browser',icon:'monitor'},{id:'notes',name:'文档',en:'Documents',icon:'file'}];
 const appIcon=id=>'<span class="office-app-icon">'+(typeof remoteAiIcon==='function'?remoteAiIcon(id):icon(apps.find(a=>a.id===id)?.icon||'terminal'))+'</span>';
 const appName=id=>{const a=apps.find(a=>a.id===id);return a?(a.en?L(a.name,a.en):a.name):id;};
 const account=()=>mobileAuth.loggedIn?mobileAuth.region+'|'+mobileAuth.accountPhone:'';
 function reset(){cancelAsync();Object.assign(state,{owner:account(),devices:{},treeOpen:{},capture:'desktop',app:'vscode',thread:'plan',origin:'detail',nativeOrigin:'office-ai',nativeContext:null,floatOpen:false,demo:'all',guideOpen:false,previewExpanded:true,previewKind:'ai',speechStatus:'idle',previewTab:0,landscape:false,zoom:1,captureOpen:false,nativeHistory:false,notice:''});}
 // Fictional hierarchy fixtures; stable legacy IDs remain available. /2026.10.29修改
 function sampleThreads(){return [
  ['plan','vscode','晴川记账','Qingchuan Ledger','新增月度预算提醒','Add monthly budget reminders'],
  ['ledger-filter','vscode','晴川记账','Qingchuan Ledger','优化账单筛选','Improve transaction filters'],
  ['travel-export','vscode','旅途清单','Travel Checklist','导出行程为 PDF','Export itinerary to PDF'],
  ['review','claude','内容工作室','Content Studio','整理春季活动文案','Draft spring campaign copy'],
  ['content-faq','claude','内容工作室','Content Studio','补充常见问题说明','Expand frequently asked questions'],
  ['workspace','workbuddy','任务','Tasks','汇总本周项目进度','Summarize weekly project progress'],
  ['task-catalog','workbuddy','任务','Tasks','归档活动素材','Archive campaign assets'],
  ['task-stats','workbuddy','任务','Tasks','校验数据统计口径','Verify metric definitions']
 ].map(([id,app,folder,folderEn,title,en],index)=>({id,app,folder,folderEn,title,en,updated:['刚刚','20 分钟前','昨天'][index%3],updatedEn:['Just now','20 min ago','Yesterday'][index%3],draft:'',messages:[{role:'user',text:L('继续处理：','Continue working on: ')+L(title,en)},{role:'assistant',text:L('已保留此主题的讨论和待处理事项，可继续核对具体内容。','The discussion and pending items for this topic are saved. Continue reviewing the details.')}]}));}
 function folders(threads){const groups=[];for(const t of threads){const key=t.folder||'__sessions';let group=groups.find(g=>g.key===key);if(!group){group={key,title:t.folder||'会话',en:t.folderEn||(t.folder?'':'Sessions'),threads:[]};groups.push(group);}group.threads.push(t);}return groups;}
 function folderTitle(group){return group.en?L(group.title,group.en):group.title;}
 function topicTime(t){return t.updatedEn?L(t.updated,t.updatedEn):t.updated||L('刚刚','Just now');}
 function treeOpen(key,fallback=false){return Object.prototype.hasOwnProperty.call(state.treeOpen,key)?state.treeOpen[key]:fallback;}
 function treeBranch(key,cls,label,content,initial=false,attrs=''){return '<details class="'+cls+'" data-office-tree="'+esc(key)+'"'+(treeOpen(key,initial)?' open':'')+' '+attrs+'><summary>'+label+'<span class="office-tree-chevron">'+icon('chevron')+'</span></summary>'+content+'</details>';}
 function topicSidebar(app,actionName='office-remote-thread',readonly=!editable()) {const rows=data().threads.filter(t=>t.app===app),row=t=>'<button class="'+(t.id===state.thread?'selected':'ghost')+'" data-action="'+actionName+':'+t.id+'"'+(readonly?' disabled':'')+'><span>'+esc(titleOf(t))+'</span><small>'+esc(topicTime(t))+'</small></button>';return '<div class="office-topic-sidebar">'+(app==='claude'?'<p class="office-recent-label">'+L('最近的','Recent')+'</p>'+rows.map(row).join(''):folders(rows).map(g=>'<details open><summary>'+icon(g.key==='任务'?'grid':'folder')+'<span>'+esc(folderTitle(g))+'</span><small>'+g.threads.length+'</small></summary>'+g.threads.map(row).join('')+'</details>').join(''))+'</div>';}
 function data(id=s.device){if(state.owner!==account())reset();return state.devices[id]||={windows:{vscode:true,claude:true,workbuddy:true,browser:true,notes:true},threads:sampleThreads(),browser:'项目工作台',notes:'项目讨论记录\n\n待办事项\n1. 核对功能范围\n2. 验证页面交互\n3. 更新交付说明\n\n'+Array.from({length:12},(_,i)=>'记录 '+(i+1)+'：继续整理电脑上的任务与工作资料。').join('\n')};}
 // Remember the last valid topic independently for each computer/client/AI account.
 function recentKey(app,dev=s.device){return app+'|'+(window.RemoteAiAccounts?.active(dev,app)||'primary');}
 function rememberTopic(id,app=state.app,dev=s.device){const d=data(dev);if(!d.threads.some(t=>t.id===id&&t.app===app))return;(d.recentTopics||={})[recentKey(app,dev)]=id;}
 function recentTopic(app,dev=s.device){const d=data(dev);if(!d.threads.some(t=>t.app===app))return '';const key=recentKey(app,dev),id=d.recentTopics?.[key];return d.threads.find(t=>t.id===id&&t.app===app)?.id||d.threads.find(t=>t.app===app)?.id||'';}
 function thread(){return data().threads.find(t=>t.id===state.thread&&t.app===state.app);}
 function titleOf(t){return t?.en?L(t.title,t.en):t?.title||'';}
 function allowed(){const d=device();return mobileAuth.loggedIn&&d&&d.online&&!d.blocked&&!isUnsupportedDevice(d);}
 function editable(){return allowed()&&!s.view;}
 function canMessage(){return editable()&&!!data().windows[state.app];}
 function button(zh,en,act,cls='ghost',ic='',disabled=false){let html=btn(L(zh,en),act,cls,ic);const aid=act.split(':')[1];if(ic&&/^(office-open-app|office-capture|quick-open):/.test(act)&&apps.some(a=>a.id===aid))html=html.replace(icon(ic),appIcon(aid));return disabled?html.replace('<button','<button disabled'):html;}
 function status(d){return !d.online?L('离线','Offline'):d.blocked?L('不允许被控','Control disabled'):d.busy?L('被控中','In use'):L('在线','Online');}
 function inlineNotice(){return state.notice?'<p class="office-notice" role="status">'+esc(state.notice)+'</p>':'';}
 function failure(){const d=device();return !d?.online?L('电脑已离线，请等待电脑恢复在线。','The computer is offline. Wait for it to reconnect.'):d.blocked?L('该电脑不允许被控，请先在电脑中开启权限。','Remote control is disabled. Enable it on the computer first.'):L('当前窗口已关闭或不可用，请选择其他窗口或返回桌面。','This window is closed or unavailable. Select another window or return to the desktop.');}
 function usageChoice(){return '<main class="usage-choice"><div class="usage-choice-inner"><span class="usage-choice-mark">'+icon('monitor')+'</span><h1>'+L('你想如何使用盖世远程？','How will you use GameHub Remote?')+'</h1><p>'+L('选择使用场景，进入对应首页。','Choose a use case to get started.')+'</p><div class="usage-choice-options">'+[['office','办公','Work','进入 AI 会话列表，继续电脑上的工作','Open AI sessions and continue your work','chat'],['other','非办公','Non-work','进入设备列表，连接你的电脑','Open devices and connect to your computer','monitor']].map(([id,zh,en,desc,descEn,ic])=>'<button data-action="usage-choice:'+id+'">'+icon(ic)+'<span><strong>'+L(zh,en)+'</strong><small>'+L(desc,descEn)+'</small></span>'+icon('chevron')+'</button>').join('')+'</div><p class="usage-choice-hint">'+L('进入后可随时切换 AI 会话和我的设备。','You can switch between AI sessions and My devices at any time.')+'</p></div></main>';}
 function connectionGuide(force=false){return '<section class="office-connection-guide">'+button('如何连接电脑与 AI 会话','Connect your computer and AI sessions','office-guide','office-guide-toggle','info')+((state.guideOpen||force)?'<ol><li>'+L('手机与电脑登录同一盖世账号。','Sign in with the same GameHub account on both devices.')+'</li><li>'+L('在电脑开启远程控制权限，并保持在线。','Enable remote control on the computer and keep it online.')+'</li><li>'+L('打开 VS Code、Claude 或 WorkBuddy，建立会话。','Open VS Code, Claude or WorkBuddy and start a session.')+'</li></ol>':'')+'</section>';}
 function sessionCard(d,t){const unavailable=!d.online||d.blocked;return '<article class="office-session-card office-topic-row '+(!d.online?'is-offline':'')+'" data-device="'+d.id+'" data-session="'+t.id+'" data-app="'+t.app+'"><button class="office-session-main" data-action="office-thread:'+d.id+':'+t.app+':'+t.id+'"'+(unavailable?' disabled':'')+'>'+icon(t.app==='workbuddy'?'file':'chat')+'<span class="grow"><strong class="device-name">'+esc(titleOf(t))+'</strong><small class="office-topic-time">'+esc(topicTime(t))+'</small></span></button><div class="office-session-secondary">'+ib(L(unavailable?'查看历史：':'预览与对话：',unavailable?'View history: ':'Preview and chat: ')+titleOf(t),'office-native:'+d.id+':'+t.app+':'+t.id,'chat')+'</div></article>';}
 function computerTree(d,initial){const threads=data(d.id).threads;const contents=apps.filter(a=>threads.some(t=>t.app===a.id)).map(a=>{const appThreads=threads.filter(t=>t.app===a.id),groups=folders(appThreads);const folderRows=a.id==='claude'?'<section class="office-claude-recent"><h3>'+L('最近的','Recent')+'</h3>'+appThreads.map(t=>sessionCard(d,t)).join('')+'</section>':groups.map((g,index)=>treeBranch(d.id+'|'+a.id+'|'+g.key,'office-folder-node',icon(a.id==='workbuddy'&&g.key==='任务'?'grid':'folder')+'<strong>'+esc(folderTitle(g))+'</strong><small>('+g.threads.length+')</small>',(a.id==='vscode'?'<div class="office-topics-heading">'+L('会话','Sessions')+'</div>':'')+g.threads.map(t=>sessionCard(d,t)).join(''),initial&&a.id==='vscode'&&index===0,'data-folder="'+esc(g.key)+'"')).join('');return treeBranch(d.id+'|'+a.id,'office-software-node office-software-group',appIcon(a.id)+'<strong>'+appName(a.id)+'</strong><small>'+appThreads.length+'</small><span class="office-software-meta"></span>',folderRows,initial&&a.id==='vscode','data-device="'+d.id+'" data-app="'+a.id+'"');}).join('');return treeBranch(d.id,'office-computer-node',icon('monitor')+'<span class="office-computer-label"><strong>'+esc(d.name)+'</strong><small class="office-device-status '+(!d.online?'offline':d.blocked?'blocked':d.busy?'busy':'online')+'">'+status(d)+'</small></span><small class="office-topic-count">'+threads.length+'</small>',contents,initial,'data-device="'+d.id+'"');}
 function sessionsPage(){const supported=state.demo==='default'?[]:devices.filter(d=>!isUnsupportedDevice(d));const rows=state.demo==='no-sessions'||s.empty?[]:supported.flatMap(d=>data(d.id).threads.map(t=>({d,t})));let content='';if(state.demo==='loading')content='<div class="office-list-loading" role="status"><span class="office-loading-ring"></span><h2>'+L('正在获取会话','Loading sessions')+'</h2><p>'+L('正在同步电脑上的 AI 会话。','Syncing AI sessions from your computers.')+'</p></div>';else if(state.demo==='error')content='<div class="blank office-list-error"><h2>'+L('暂时无法获取会话','Unable to load sessions')+'</h2><p>'+L('请检查网络后重试。','Check your connection and try again.')+'</p>'+button('重试','Retry','office-retry','primary')+'</div>';else if(!rows.length)content='<div class="blank office-session-empty"><h2>'+L(supported.length?'暂无 AI 会话':'暂无已连接的电脑',supported.length?'No AI sessions':'No connected computers')+'</h2><p>'+L(supported.length?'先在电脑客户端中建立会话。':'添加电脑后，可在手机继续电脑上的工作。',supported.length?'Start a session in a computer client.':'Connect a computer to continue your work on your phone.')+'</p></div>';else content=[true,false].map(online=>{const group=rows.filter(({d})=>!!d.online===online),computers=supported.filter(d=>!!d.online===online&&group.some(row=>row.d.id===d.id)),firstOnline=supported.find(d=>d.online)?.id;return '<section class="office-session-group" data-group="'+(online?'online':'offline')+'"><h2>'+L(online?'在线会话':'离线会话',online?'Online sessions':'Offline sessions')+'<span class="office-group-count">'+group.length+'</span></h2>'+(computers.length?computers.map(d=>computerTree(d,d.id===firstOnline)).join(''):'<p class="office-group-empty">'+L(online?'暂无在线会话':'暂无离线会话',online?'No online sessions':'No offline sessions')+'</p>')+'</section>';}).join('');return head(L('AI 会话','AI sessions'),false)+'<main class="content office-ai-list">'+inlineNotice()+connectionGuide(!rows.length&&!['loading','error'].includes(state.demo))+content+'</main>';}
 function demoControls(){return '<section class="office-demo-controls" aria-label="演示状态"><strong>'+L('演示状态','Demo states')+'</strong>'+[['default','缺省态·无设备','Default · no devices'],['all','穷举态·全部','All states'],['no-sessions','无会话','No sessions'],['loading','加载中','Loading'],['error','失败','Error'],['offline','全部离线','All offline'],['blocked','禁控','Control disabled'],['busy','忙碌','Busy'],['preview','预览与对话','Preview and chat'],['preview-closed','预览已关闭','Preview closed']].map(([id,zh,en])=>button(zh,en,'office-demo:'+id,state.demo===id?'selected':'ghost','',!mobileAuth.loggedIn)).join('')+'</section>';}
 function applyDemo(mode){if(!mobileAuth.loggedIn||!['default','all','no-sessions','loading','error','offline','blocked','busy','preview','preview-closed'].includes(mode))return;data();clearTimeout(connectTimer);s.modal='';s.panel='';s.pendingAction='';state.floatOpen=false;state.captureOpen=false;state.landscape=false;state.notice='';state.demo=mode;s.empty=mode==='default';s.loading=false;s.view=false;devices=structuredClone(initialDevices);s.device='win';if(mode==='offline')devices.forEach(d=>d.online=false);if(mode==='blocked')devices.filter(d=>!isUnsupportedDevice(d)).forEach(d=>{d.online=true;d.blocked=true;});if(mode==='busy')devices.filter(d=>!isUnsupportedDevice(d)).forEach(d=>{d.online=true;d.blocked=false;d.busy=true;});if(mode==='all')Object.values(state.devices).forEach(d=>Object.keys(d.windows).forEach(k=>d.windows[k]=true));s.page='office-ai';if(mode==='preview'||mode==='preview-closed'){data('win').windows.browser=mode==='preview';state.previewKind=mode==='preview-closed'?'web':'ai';state.previewExpanded=true;openNative('win','vscode',data('win').threads.find(t=>t.app==='vscode')?.id||'');return;}render();}
 function officeNewAction(k,v,p){if(k==='office-demo'){applyDemo(v);return true;}if(k==='office-guide'){if(mobileAuth.loggedIn){state.guideOpen=!state.guideOpen;render();}return true;}if(k==='office-retry'){applyDemo('all');return true;}if(k==='office-preview-kind'){if(['ai','web'].includes(v)){state.previewKind=v;render();}return true;}if(k==='office-preview-toggle'){state.previewExpanded=!state.previewExpanded;render();return true;}if(k==='office-preview-tab'){if(editable()&&data().windows.browser){state.previewTab=Number(v)===1?1:0;data().browser=state.previewTab?L('项目资料已展开','Project files opened'):L('项目工作台','Project workspace');render();}return true;}if(k==='office-preview-expand'){const target=state.previewKind==='web'?'browser':state.app;if(!allowed()||!data().windows[target])return true;begin(s.device,target,target==='browser'?'':state.thread,'office-native',s.view);return true;}return false;}
 const oldList=list;list=function(){return s.page==='usage-choice'?usageChoice():s.page==='office-ai'?sessionsPage():s.page==='office-native'?nativePage():oldList();};
 mobileRootNav=function(){if(!mobileAuth.loggedIn||!['list','office-ai','mobile-profile'].includes(s.page))return '';return '<nav class="bottom mobile-root-tabs" role="tablist" aria-label="'+L('主导航','Main navigation')+'">'+[['ai','office-ai','AI 会话','AI sessions','chat'],['devices','list','我的设备','My devices','monitor'],['profile','mobile-profile','我的','Me','user']].map(([key,page,zh,en,ic])=>'<button role="tab" aria-selected="'+(s.page===page)+'" class="'+(s.page===page?'selected':'')+'" data-action="mobile-tab:'+key+'">'+icon(ic)+'<span>'+L(zh,en)+'</span></button>').join('')+'</nav>';};
 quickCatalog=function(){return apps.map(a=>({...a,name:appName(a.id)}));};
 quickApps=function(){s.quickAppsByDevice||={};const saved=s.quickAppsByDevice[s.device];return s.quickAppsByDevice[s.device]=Array.isArray(saved)&&saved.some(x=>apps.some(a=>a.id===x))?saved.filter(x=>apps.some(a=>a.id===x)):['vscode','claude','workbuddy'];};
 gptQuickLaunch=function(){return '<div class="gpt-quick-row office-quick-row">'+quickApps().map(id=>button(appName(id),appName(id),'quick-open:'+id,'gpt-quick',apps.find(a=>a.id===id).icon,!allowed())).join('')+button('添加应用','Add app','quicklaunch','gpt-add','plus')+'</div>';};
 function begin(deviceId,app='desktop',threadId='',origin='detail',view=false){const d=devices.find(d=>d.id===deviceId);if(!mobileAuth.loggedIn||!d||isUnsupportedDevice(d))return;clearTimeout(connectTimer);s.device=d.id;data(d.id);state.notice='';if(!d.online||d.blocked){state.notice=failure();render();return;}if(!['desktop',...apps.map(a=>a.id)].includes(app))return;if(app!=='desktop'&&threadId&&!data().threads.some(t=>t.id===threadId&&t.app===app)){state.notice=L('此会话已不可用。','This session is no longer available.');render();return;}if(origin==='office-native')state.nativeContext={device:deviceId,app:state.app,thread:state.thread,view:s.view};state.origin=origin;state.capture=app;state.app=app==='desktop'?'vscode':app;state.thread=threadId||recentTopic(state.app);rememberTopic(state.thread);state.zoom=1;state.captureOpen=false;state.floatOpen=false;state.landscape=false;s.mode='office';s.mapping=false;s.virtualPad=false;s.gameActive=false;s.gptDesktop=false;s.panel='';s.pendingAction=d.busy?'office-start:'+d.id+':'+app+':'+state.thread+':'+origin+':'+(view?'view':'control'):'';requestConnection(view?'view':'control');}
 function captureOptions(){return '<section class="office-capture-panel" role="dialog" aria-label="'+L('选择串流对象','Choose capture target')+'"><div class="row spread"><h3>'+L('选择串流对象','Choose capture target')+'</h3>'+ib(L('关闭','Close'),'office-capture-panel','close')+'</div>'+button('全桌面','Entire desktop','office-capture:desktop',state.capture==='desktop'?'primary':'ghost','monitor')+apps.map(a=>'<button data-action="office-capture:'+a.id+'" class="'+(state.capture===a.id?'active':'')+'"'+(!data().windows[a.id]?' disabled':'')+'>'+appIcon(a.id)+'<span>'+appName(a.id)+'<small>'+(!data().windows[a.id]?L('窗口已关闭','Window closed'):L('指定应用窗口','Application window'))+'</small></span></button>').join('')+'</section>';}
 function legacyRemoteApp(id){if(!data().windows[id])return '<section class="office-unavailable"><h3>'+L('窗口不可用','Window unavailable')+'</h3><p>'+failure()+'</p>'+button('选择其他窗口','Choose another window','office-capture-panel','primary')+button('返回桌面','Return to desktop','office-desktop')+'</section>';const ai=['vscode','claude','workbuddy'].includes(id),t=thread();return '<section class="office-remote-app remote-window" data-captured-app="'+id+'"><header class="office-app-titlebar"><span>'+appIcon(id)+appName(id)+'</span>'+ib(L('关闭远端窗口','Close remote window'),'office-close-window','close').replace('<button','<button '+(!editable()?'disabled':''))+'</header>'+(ai?'<div class="office-desktop-app-body"><aside class="office-app-sidebar"><strong>'+appName(id)+'</strong>'+data().threads.filter(x=>x.app===id).map(x=>'<button data-action="office-remote-thread:'+x.id+'" class="'+(x.id===state.thread?'selected':'')+'"'+(!editable()?' disabled':'')+'>'+esc(titleOf(x))+'</button>').join('')+'</aside><div class="office-app-main"><h3 class="device-name">'+esc(titleOf(t)||L('暂无会话','No session'))+'</h3><div class="office-remote-scroll" tabindex="0">'+(t?t.messages.map(m=>'<article><small>'+esc(m.role==='user'?L('你','You'):appName(id))+'</small><p class="device-name">'+esc(m.text)+'</p>'+(window.RemotePhoneMedia?.message(m)||'')+'</article>').join('')+Array.from({length:8},(_,i)=>'<div class="office-remote-log">'+L('工作记录','Work log')+' '+(i+1)+'<p>'+L('当前项目资料与任务清单。','Current project files and task checklist.')+'</p></div>').join(''):'<p>'+L('请在电脑中建立会话。','Start a session on the computer.')+'</p>')+'</div><form id="office-remote-form"><textarea id="office-remote-input" class="doc" aria-label="'+L('远端应用输入','Remote app input')+'" '+(!editable()||!t?'readonly':'')+'>'+esc(t?.draft||'')+'</textarea>'+button('发送','Send','office-send','primary','',!editable()||!t)+'</form></div></div>':id==='browser'?'<div class="office-browser"><div class="office-address">https://workspace.example / '+L('工作台','Workspace')+'</div><div class="office-remote-scroll"><h2>'+L('项目工作台','Project workspace')+'</h2>'+['项目资料','讨论记录','任务清单'].map((x,i)=>button(x,['Project files','Discussion notes','Task checklist'][i],'office-browser:'+i,'ghost','file',!editable())).join('')+'<article id="office-browser-content">'+esc(data().browser)+'</article></div></div>':'<textarea id="office-document" class="office-document doc" aria-label="'+L('远端文档','Remote document')+'" '+(!editable()?'readonly':'')+'>'+esc(data().notes)+'</textarea>')+'</section>';}
 function desktop(){return '<div class="office-desktop"><div class="office-desktop-icons">'+apps.map(a=>button(appName(a.id),appName(a.id),'office-open-app:'+a.id,'office-desktop-icon',a.icon,!editable())).join('')+'</div><div class="office-desktop-center">'+icon('monitor')+'<strong>'+esc(device().name)+'</strong></div><div class="office-desktop-taskbar">'+icon('grid')+apps.filter(a=>data().windows[a.id]).map(a=>button(appName(a.id),appName(a.id),'office-capture:'+a.id,'ghost',a.icon)).join('')+'</div></div>';}
 operationPanel=function(){return '<div class="row spread"><h3>'+L('操作','Controls')+'</h3>'+ib(L('关闭','Close'),'panel-close','close')+'</div><div class="squares">'+button('退出远控','Exit remote','office-back','','power')+button('旋转屏幕','Rotate screen','rotate','','refresh')+button(s.sound?'声音':'静音',s.sound?'Sound':'Muted','toggle:sound','','volume')+button(s.view?'恢复控制':'仅观看',s.view?'Resume control':'View only','toggle-view','','monitor')+'</div>'+line(L('显示','Display'),'panel:display','monitor')+line(L('声音','Sound'),'panel:sound','volume')+line(L('安全','Security'),'panel:security','shield')+line(L('键盘与快捷键','Keyboard and shortcuts'),'panel:keyboard','keyboard','',s.view);};
 session=function(){const unavailable=!allowed(),target=state.capture==='desktop'?L('全桌面','Entire desktop'):appName(state.capture);const panel=s.panel==='operation'?operationPanel():s.panel==='keyboard'?keyboardPanel():s.panel==='text'?textPanel():s.panel==='display'?displayPanel():s.panel==='security'?sessionSecurityPanel():s.panel==='sound'?'<div class="row spread"><h3>'+L('声音','Sound')+'</h3>'+ib(L('关闭','Close'),'panel-close','close')+'</div>'+toggle('sound',L('电脑声音','Computer sound')):'';return '<section class="office-stream" data-capture="'+state.capture+'"><header class="office-stream-head">'+ib(L('返回','Back'),'office-back','back')+'<div class="grow"><strong>'+esc(device().name)+'</strong><small>'+L('串流对象：','Capture: ')+target+(s.view?' · '+L('仅观看','View only'):'')+'</small></div>'+button('切换','Switch','office-capture-panel','ghost','grid')+'</header>'+inlineNotice()+'<div class="office-screen-viewport"><div class="office-screen-content" style="transform:scale('+state.zoom+')">'+(unavailable?'<div class="office-unavailable" role="status">'+failure()+'</div>':state.capture==='desktop'?desktop():'<div class="office-desktop-frame"><div class="office-desktop-coordinate">'+remoteApp(state.capture)+'</div></div>')+'</div></div><div class="office-zoom-tools">'+button('缩小','Zoom out','office-zoom:out')+'<output>'+Math.round(state.zoom*100)+'%</output>'+button('放大','Zoom in','office-zoom:in')+button('复位','Reset','office-zoom:reset')+'</div>'+(panel?'<section class="session-panel office-control-panel">'+panel+'</section>':'')+floatingTools()+(state.captureOpen?captureOptions():'')+'</section>';};
 function openNative(dev,app,tid){const d=devices.find(d=>d.id===dev);if(!mobileAuth.loggedIn||!d||!['vscode','claude','workbuddy'].includes(app))return;s.device=dev;if(!data().threads.some(t=>t.id===tid&&t.app===app))return;state.nativeOrigin=s.page==='office-native'?state.nativeOrigin:s.page==='session'?state.origin:'office-ai';state.app=app;state.thread=tid;rememberTopic(tid);state.notice='';state.nativeHistory=false;const fromStream=s.page==='session';s.page='office-native';s.panel='';if(!fromStream)s.view=false;render();}
 function remoteConversation(id,t){return '<section class="office-client-chat"><header>'+L('AI 对话','AI chat')+'<span>'+appName(id)+'</span></header><div class="office-remote-scroll" tabindex="0">'+(t?t.messages.map(m=>'<article class="office-desktop-message"><small>'+esc(m.role==='user'?L('你','You'):appName(id))+'</small><p class="device-name">'+esc(m.text)+'</p>'+(window.RemotePhoneMedia?.message(m)||'')+'</article>').join(''):'')+Array.from({length:6},(_,i)=>'<div class="office-remote-log">'+L('工作记录','Work log')+' '+(i+1)+'<p>'+L('当前项目资料与待核对事项。','Current project files and items for review.')+'</p></div>').join('')+'</div><form id="office-remote-form"><textarea id="office-remote-input" class="doc" aria-label="'+L('远端应用输入','Remote app input')+'" '+(!canMessage()||!t?'readonly':'')+'>'+esc(t?.draft||'')+'</textarea>'+button('发送','Send','office-send','primary','',!canMessage()||!t)+'</form></section>';}
 function remoteApp(id){if(id==='browser'&&data().windows.browser)return '<section class="office-remote-app remote-window office-captured-browser" data-captured-app="browser"><header class="office-app-titlebar"><span>'+appIcon('browser')+appName('browser')+'</span>'+ib(L('关闭远端窗口','Close remote window'),'office-close-window','close').replace('<button','<button '+(!editable()?'disabled':''))+'</header>'+webContent()+'</section>';if(!['vscode','claude','workbuddy'].includes(id)||!data().windows[id])return legacyRemoteApp(id);const t=thread();const sidebar='<aside class="office-client-sidebar"><strong>'+appName(id)+'</strong>'+(id==='claude'?'':'<label>'+L('最近任务','Recent tasks')+'</label>')+topicSidebar(id)+'<div class="office-sidebar-foot">'+L('本机工作区','Local workspace')+'</div></aside>';const editor='<section class="office-vscode-editor"><div class="office-editor-tabs">App.tsx <span>README.md</span></div><pre><span>1</span> import { useState } from "react";\n<span>2</span>\n<span>3</span> export default function App() {\n<span>4</span>   const [page, setPage] = useState("home");\n<span>5</span>\n<span>6</span>   return (\n<span>7</span>     &lt;main className="workspace"&gt;\n<span>8</span>       &lt;Header /&gt;\n<span>9</span>       &lt;ProjectList /&gt;\n<span>10</span>    &lt;/main&gt;\n<span>11</span>  );\n<span>12</span> }</pre><div class="office-editor-terminal"><strong>TERMINAL</strong><p>~/project $ npm run dev</p><p>Local: http://localhost:3000</p><span>Ready · watching for changes</span></div></section>';const fileTree='<aside class="office-file-tree office-vscode-topics"><strong>'+L('会话','Sessions')+'</strong>'+topicSidebar(id)+'</aside>';const tasks='<section class="office-workbuddy-board"><header><small>WORKSPACE / PROJECT</small><h2>'+L('项目工作区','Project workspace')+'</h2><p>'+L('文件、任务和执行记录','Files, tasks and activity')+'</p></header><div class="office-workspace-tabs">'+L('概览　　任务　　文件','Overview　　Tasks　　Files')+'</div><div class="office-workspace-task"><span>✓</span><div><b>'+L('整理项目资料','Organize project files')+'</b><small>'+L('已整理 6 个文件','6 files organized')+'</small></div></div><div class="office-workspace-task"><span>◷</span><div><b>'+L('核对实现与验证步骤','Review implementation and verification')+'</b><small>'+L('当前任务','Current task')+'</small></div></div><div class="office-workspace-files"><b>'+L('工作区文件','Workspace files')+'</b><p>📄 requirements.md</p><p>📄 implementation-plan.md</p><p>📁 project-assets</p></div></section>';return '<section class="office-remote-app remote-window office-desktop-client office-client-'+id+'" data-captured-app="'+id+'"><header class="office-app-titlebar"><span>'+appIcon(id)+appName(id)+' — '+esc(titleOf(t))+'</span>'+ib(L('关闭远端窗口','Close remote window'),'office-close-window','close').replace('<button','<button '+(!editable()?'disabled':''))+'</header><div class="office-client-body">'+(id==='vscode'?'<nav class="office-vscode-activity">'+icon('file')+icon('search')+icon('terminal')+icon('settings')+'</nav>'+fileTree+editor:sidebar+(id==='workbuddy'?tasks:''))+remoteConversation(id,t)+'</div><footer class="office-client-status">'+(id==='vscode'?'main　✓ 0　△ 0　　TypeScript React　UTF-8':id==='claude'?L('当前电脑 · 会话已保存','This computer · session saved'):L('工作区已同步 · 本地任务','Workspace synced · local tasks'))+'</footer></section>';}
 function webContent(){return '<div class="office-preview-browser"><div class="office-preview-address">localhost:3000 / '+L('项目工作台','Project workspace')+'</div><nav>'+button('概览','Overview','office-preview-tab:0',state.previewTab===0?'selected':'ghost','',!editable())+button('项目资料','Project files','office-preview-tab:1',state.previewTab===1?'selected':'ghost','',!editable())+'</nav><article class="office-preview-content" data-preview-tab="'+state.previewTab+'">'+(state.previewTab?'<strong>'+L('项目资料','Project files')+'</strong><p>requirements.md　 ·　 implementation-plan.md</p>':'<strong>'+L('让项目进展一目了然','Your project at a glance')+'</strong><p>'+L('查看当前任务与工作区文件。','Review current tasks and workspace files.')+'</p><div class="office-preview-stats"><span>6 '+L('文件','files')+'</span><span>2 '+L('任务','tasks')+'</span></div>')+'</article></div>';}
 function replyStatus(){return [...pendingReplies.values()].some(job=>sameContext(job.ctx))?'<p class="office-ai-reply-status" role="status" aria-live="polite">'+L('正在回复…','Replying…')+'</p>':'';}
 function aiPreview(){const t=thread();return '<div class="office-ai-preview" data-thread="'+esc(t?.id||'')+'"><div class="office-ai-preview-title">'+appIcon(state.app)+'<span>'+appName(state.app)+'</span><small>'+esc(titleOf(t))+'</small></div><div class="office-ai-preview-messages" aria-label="'+L('电脑 AI 对话内容','Computer AI conversation')+'">'+(t?t.messages.slice(-4).map(m=>'<article class="'+m.role+'"><small>'+esc(m.role==='user'?L('你','You'):appName(state.app))+'</small><p>'+esc(m.text||L('图片附件','Image attachment'))+'</p>'+(window.RemotePhoneMedia?.message(m)||'')+'</article>').join(''):'')+replyStatus()+'</div></div>';}
 function previewPanel(){const ai=state.previewKind!=='web',target=ai?state.app:'browser',available=allowed()&&data().windows[target];return '<section class="office-native-preview '+(!state.previewExpanded?'is-collapsed':'')+'" data-preview-kind="'+(ai?'ai':'web')+'" data-preview-state="'+(!allowed()?(!device()?.online?'offline':'blocked'):!data().windows[target]?'closed':'ready')+'"><header><div class="office-preview-modes" role="group" aria-label="'+L('预览内容','Preview content')+'">'+button('电脑对话','Computer chat','office-preview-kind:ai',ai?'selected':'ghost')+button('网页预览','Web preview','office-preview-kind:web',ai?'ghost':'selected')+'</div><div>'+button(state.previewExpanded?'收起':'展开',state.previewExpanded?'Collapse':'Expand','office-preview-toggle','ghost')+button('放大','Expand stream','office-preview-expand','ghost','',!available)+'</div></header>'+(state.previewExpanded?(available?(ai?aiPreview():webContent()):'<div class="office-preview-unavailable" role="status">'+(!allowed()?failure():ai?L('AI 客户端窗口已关闭，请在电脑重新打开后查看对话。','The AI client window is closed. Reopen it on the computer to view the conversation.'):L('浏览器窗口已关闭。请在电脑重新打开后查看预览。','The browser window is closed. Reopen it on the computer to preview.'))+'</div>'):'')+'</section>';}
 function nativePage(){const t=thread(),canSend=canMessage()&&!!t;return '<section class="office-native-workspace"><header class="head">'+ib(L('返回','Back'),'office-back','back')+'<h1>'+appName(state.app)+'</h1>'+button('会话','Sessions','office-native-history','ghost','menu')+button('串流','Stream','office-native-stream','ghost','monitor',!allowed()||!data().windows[state.app])+'</header><h2 class="office-native-title device-name">'+esc(titleOf(t))+'<small>'+esc(device()?.name||'')+' · '+status(device())+'</small></h2>'+previewPanel()+'<main class="content office-native-messages">'+(!allowed()?'<p class="office-history-notice" role="status">'+L('仅展示已保存的会话历史；电脑恢复在线并允许远控后可继续。','Saved conversation history only. Reconnect and enable control to continue.')+'</p>':!data().windows[state.app]?'<p class="office-history-notice">'+L('AI 客户端窗口已关闭，重新打开后可继续对话。','The AI client window is closed. Reopen it to continue.')+'</p>':'')+(t?t.messages.map(m=>'<article class="office-native-message '+m.role+'"><small>'+esc(m.role==='user'?L('你','You'):appName(state.app))+'</small><p class="device-name">'+esc(m.text)+'</p>'+(window.RemotePhoneMedia?.message(m)||'')+'</article>').join(''):'')+replyStatus()+'</main><form id="office-native-form" data-speech-state="'+state.speechStatus+'">'+(window.RemotePhoneMedia?.composer(t)||'')+'<textarea id="office-native-input" placeholder="'+L('发消息或按住说话','Send a message or hold to talk')+'" aria-label="'+L('发消息或按住说话','Send a message or hold to talk')+'" '+(!canSend?'readonly':'')+'>'+esc(t?.draft||'')+'</textarea><button type="button" class="office-voice-button" aria-label="'+L('按住说话，松开发送（模拟）','Hold to talk, release to send (demo)')+'" aria-pressed="false"'+(!canSend?' disabled':'')+'>'+voiceIcon()+'</button>'+button('发送','Send','office-native-send','primary','',!canSend)+'<p class="office-voice-status" role="status" aria-live="polite"></p>'+'</form>'+inlineNotice()+(state.nativeHistory?'<aside class="office-native-history"><div class="row spread"><strong>'+esc(device().name)+' · '+appName(state.app)+'</strong>'+ib(L('关闭','Close'),'office-native-history','close')+'</div>'+topicSidebar(state.app,'office-native-select',false)+'</aside>':'')+'</section>';}
 function fitDesktop(){const host=document.querySelector('.office-desktop-frame'),canvas=host?.querySelector('.office-desktop-coordinate');if(!host||!canvas)return;const fit=Math.min(host.clientWidth/1100,host.clientHeight/680);canvas.style.transform='scale('+fit+')';canvas.style.left=(host.clientWidth-1100*fit)/2+'px';canvas.style.top=(state.zoom>1?0:(host.clientHeight-680*fit)/2)+'px';}
 // Reply and voice jobs never outlive their exact account/device/client/topic context.
 function context(){return {owner:account(),device:s.device,app:state.app,ai:window.RemoteAiAccounts?.active(s.device,state.app)||'primary',thread:state.thread,ref:thread(),page:s.page};}
 function sameContext(c){return !!c&&c.owner===account()&&c.device===s.device&&c.app===state.app&&c.ai===(window.RemoteAiAccounts?.active(s.device,state.app)||'primary')&&c.thread===state.thread&&c.ref===thread()&&c.page===s.page;}
 function contextWritable(c){return sameContext(c)&&['office-native','session'].includes(s.page)&&canMessage()&&!!thread();}
 function cancelSpeech(){if(speech)clearTimeout(speech.timer);speech=null;state.speechStatus='idle';paintSpeech();}
 function cancelAsync(){for(const job of pendingReplies.values())clearTimeout(job.timer);pendingReplies.clear();cancelSpeech();}
 function guardAsync(){if(speech&&!contextWritable(speech.ctx))cancelSpeech();for(const [id,job] of pendingReplies)if(!contextWritable(job.ctx)){clearTimeout(job.timer);pendingReplies.delete(id);}}
 function simulatedReply(text,t,hasImages){const key=(t.id+' '+t.title+' '+text).toLowerCase();if(hasImages)return L('已查看这张示例图片。建议先核对主体信息和文字层级，再调整留白与对齐；可以继续指出希望修改的区域。','I reviewed the sample image. Check the main information and text hierarchy, then refine spacing and alignment. You can identify the area to revise next.');if(/pdf|行程|travel/.test(key))return L('行程导出建议按日期分组，每天从新页开始，并保留地点、时间和备注。接下来可用两天行程检查分页与中文字体。','Group the itinerary by date, start each day on a new page, and retain locations, times and notes. Test pagination and fonts with a two-day itinerary.');if(/筛选|账单|filter/.test(key))return L('账单筛选可组合日期范围、收入/支出和分类。切换条件后保留当前选择，清空时恢复全部账单，并显示筛选后的笔数与合计。','Combine date range, income/expense and category filters. Keep the selected criteria, reset to all transactions when cleared, and show the filtered count and total.');if(/预算|budget|plan/.test(key))return L('月度预算提醒可在已用金额达到预算的 80% 时触发一次，达到 100% 时再提醒。跨月重置提醒记录，修改预算后重新计算剩余额度。','Send one reminder at 80% of the monthly budget and another at 100%. Reset reminder records each month and recalculate the remaining amount when the budget changes.');if(/文案|问题|content|review|faq/.test(key))return L('建议先用一句话说明活动对象和主要收益，再补充参与时间、方式与限制。常见问题按报名、使用和售后三组整理，每条给出直接答案。','State the audience and main benefit in one sentence, followed by timing, participation and limits. Group FAQs by registration, usage and support, with direct answers.');return L('可以按“已完成、进行中、待确认”整理本周事项，为每项补充负责人和截止时间。素材按用途归档，数据同时注明统计周期、去重规则与来源。','Organize this week’s items into completed, in progress and awaiting confirmation, with owners and deadlines. Archive assets by purpose and document reporting periods, deduplication and sources.');}
 function scrollMessages(){requestAnimationFrame(()=>{for(const selector of ['.office-native-messages','.office-ai-preview-messages','.office-remote-scroll']){const el=document.querySelector(selector);if(el)el.scrollTop=el.scrollHeight;}});}
 function send(voiceText){if(!canMessage()||!thread()||!['office-native','session'].includes(s.page))return;const voice=typeof voiceText==='string',t=thread(),text=voice?voiceText.trim():t.draft.trim(),hasImages=!voice&&!!window.RemotePhoneMedia?.hasAttachments(t);if(!text&&!hasImages)return;const ctx=context();if(voice||!window.RemotePhoneMedia?.send(t,text))t.messages.push({role:'user',text});if(!voice)t.draft='';state.notice='';const id=++replySequence,job={ctx,timer:null};pendingReplies.set(id,job);job.timer=setTimeout(()=>{if(pendingReplies.get(id)!==job)return;pendingReplies.delete(id);if(!contextWritable(ctx))return;t.messages.push({role:'assistant',text:simulatedReply(text,t,hasImages),simulated:true});render();scrollMessages();},800);render();scrollMessages();}
 function voiceIcon(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="9" y="3" width="6" height="12" rx="3"/><path d="M6 11v1a6 6 0 0 0 12 0v-1M12 18v3M8 21h8"/></svg>';}
 function paintSpeech(){const active=state.speechStatus==='recording',form=document.querySelector('#office-native-form');if(form)form.dataset.speechState=state.speechStatus;document.querySelector('.office-voice-button')?.setAttribute('aria-pressed',String(active));const label=document.querySelector('.office-voice-status');if(label)label.textContent=active?L('松开发送，移出输入区或按 Esc 取消（模拟转写）','Release to send; move outside or press Esc to cancel (simulated transcription)'):'';}
 function speechText(){const key=state.thread+' '+titleOf(thread());return /filter|筛选/.test(key)?L('请补充按日期和分类筛选账单的规则。','Please add rules for filtering transactions by date and category.'):/travel|行程/.test(key)?L('请检查行程导出 PDF 的分页效果。','Please check pagination in the itinerary PDF.'):/plan|预算/.test(key)?L('请补充月度预算提醒的触发条件。','Please add the trigger conditions for monthly budget reminders.'):/review|content|文案|问题/.test(key)?L('请把活动说明整理得更简洁一些。','Please make the campaign explanation more concise.'):L('请汇总本周项目进度和待确认事项。','Please summarize this week’s project progress and open questions.');}
 function startSpeech(el,pointer,key){if(speech||s.page!=='office-native'||!canMessage()||!thread())return;const job={ctx:context(),el,rect:el.getBoundingClientRect(),pointer,key,timer:null};speech=job;state.speechStatus='pending';paintSpeech();job.timer=setTimeout(()=>{if(speech!==job||!contextWritable(job.ctx)){cancelSpeech();return;}state.speechStatus='recording';paintSpeech();},350);}
 function finishSpeech(){const job=speech,recording=state.speechStatus==='recording';if(!job)return;const valid=contextWritable(job.ctx),text=recording&&valid?speechText():'';cancelSpeech();if(text)send(text);}
 function back(){clearTimeout(connectTimer);s.pendingAction='';state.floatOpen=false;state.captureOpen=false;state.nativeHistory=false;state.zoom=1;state.notice='';s.panel='';s.modal='';const keepView=s.view;s.view=false;s.page=s.page==='office-native'?state.nativeOrigin:state.origin;if(s.page==='office-native'&&state.nativeContext){s.device=state.nativeContext.device;state.app=state.nativeContext.app;state.thread=state.nativeContext.thread;s.view=keepView||state.nativeContext.view;}if(!['office-ai','detail','office-native'].includes(s.page))s.page='detail';state.landscape=false;render();}
 const oldRemoteText=remoteText,oldWriteRemote=writeRemote;
 remoteText=function(){if(s.page==='session'&&state.capture!=='desktop')return ['vscode','claude','workbuddy'].includes(state.capture)?thread()?.draft||'':state.capture==='notes'?data().notes:'';return oldRemoteText();};
 writeRemote=function(text){if(!editable())return;if(s.page==='session'&&['vscode','claude','workbuddy'].includes(state.capture)){if(thread())thread().draft=text;}else if(s.page==='session'&&state.capture==='notes')data().notes=text;else oldWriteRemote(text);};
 const oldClear=mobileClearAccountState;mobileClearAccountState=function(){reset();return oldClear();};
 function floatingTools(){return '<aside class="office-floating-tools" aria-label="'+L('悬浮工具','Floating controls')+'">'+(state.floatOpen?'<div class="office-floating-menu">'+button('键盘','Keyboard','panel:keyboard','','keyboard',!editable())+button('选择窗口','Choose window','office-capture-panel','','grid')+button('全桌面','Desktop','office-desktop','','monitor')+button('旋转屏幕','Rotate screen','rotate','','refresh')+button('操作','Controls','panel:operation','','settings')+'</div>':'')+'<button class="office-float-toggle" data-action="office-float-toggle" aria-expanded="'+state.floatOpen+'" aria-label="'+(state.floatOpen?L('收起工具','Collapse controls'):L('展开工具','Expand controls'))+'">'+icon(state.floatOpen?'close':'settings')+'</button></aside>'; }
 const oldAction=action;
 function blocked(a){return /^(gpt-game|gpt-steam|rlc:|mapping|virtual-key|toggle:(mapping|virtualPad)|panel:mapping|mode:game|review|state:|mobile-preview:|compare$|demo-platform:)/.test(a);}
 action=function(a){if(a.startsWith('usage-choice:')){if(!mobileAuth.loggedIn||s.page!=='usage-choice')return;const choice=a.split(':')[1];if(!['office','other'].includes(choice))return;s.page=choice==='office'?'office-ai':'list';s.modal='';render();return;}const p=a.split(':'),k=p[0],v=p[1];if(officeNewAction(k,v,p))return;if(k==='office-float-toggle'){state.floatOpen=!state.floatOpen;state.captureOpen=false;s.panel='';render();return;}if(k==='panel'){state.floatOpen=false;state.captureOpen=false;}if(blocked(a)){s.gameActive=false;s.mapping=false;s.virtualPad=false;s.review=false;return;}if(k==='mobile-tab'&&v==='ai'){if(!mobileAuth.loggedIn)return;state.notice='';s.page='office-ai';s.panel='';render();return;}if(k==='mobile-tab'){state.notice='';state.landscape=false;return oldAction(a);}if(k==='office-thread'||k==='office-start'){begin(p[1],p[2],p[3],p[4]||'office-ai',p[5]==='view');return;}if(k==='office-native'){openNative(p[1],p[2],p[3]);return;}if(k==='office-native-stream'){begin(s.device,state.app,state.thread,'office-native',s.view);return;}if(k==='office-native-history'){state.nativeHistory=!state.nativeHistory;render();return;}if(k==='office-native-select'){if(data().threads.some(t=>t.id===v&&t.app===state.app)){state.thread=v;rememberTopic(v);}state.nativeHistory=false;render();return;}if(k==='office-back'||['exit','exit-confirm'].includes(k)&&s.page==='session'){back();return;}if(k==='quick-open'){if(!apps.some(x=>x.id===v))return;begin(s.device,v,'','detail');return;}if(['connect','watch'].includes(k)){begin(s.device,'desktop','','detail',k==='watch');return;}if(k==='office-capture-panel'||k==='windows'){state.captureOpen=!state.captureOpen;state.floatOpen=false;s.panel='';render();return;}if(k==='office-capture'||k==='window'){if(!['desktop',...apps.map(x=>x.id)].includes(v))return;if(v!=='desktop'&&!data().windows[v]){state.notice=failure();render();return;}rememberTopic(state.thread);state.capture=v;state.app=v==='desktop'?state.app:v;state.thread=recentTopic(state.app);rememberTopic(state.thread);state.captureOpen=false;state.zoom=1;s.panel='';state.notice='';render();return;}if(['office-desktop','desktop'].includes(k)){state.floatOpen=false;state.capture='desktop';state.captureOpen=false;state.zoom=1;s.panel='';render();return;}if(k==='office-open-app'){if(!editable()||!apps.some(a=>a.id===v))return;data().windows[v]=true;action('office-capture:'+v);return;}if(k==='office-close-window'){if(!editable()||state.capture==='desktop')return;data().windows[state.capture]=false;render();return;}if(k==='office-remote-thread'){if(!editable())return;if(data().threads.some(t=>t.id===v&&t.app===state.app)){state.thread=v;rememberTopic(v);}render();return;}if(k==='office-browser'){if(!editable())return;data().browser=[L('项目资料已展开','Project files opened'),L('讨论记录已展开','Discussion notes opened'),L('任务清单已展开','Task checklist opened')][Number(v)]||'';render();return;}if(k==='office-send'||k==='office-native-send'){send();return;}if(k==='office-zoom'){state.zoom=v==='reset'?1:Math.max(1,Math.min(2.5,state.zoom+(v==='in'?.25:-.25)));state.notice=L('画面缩放 ','View scale ')+Math.round(state.zoom*100)+'%';render();return;}if(k==='rotate'){if(s.page!=='session')return;state.floatOpen=false;state.landscape=!state.landscape;s.panel='';render();return;}if(k==='toggle-view'){if(s.page!=='session')return;if(s.view&&!allowed()){state.notice=failure();render();return;}s.view=!s.view;s.panel='';render();return;}if(k==='gpt-launch'){openNative(s.device,'vscode',recentTopic('vscode'));return;}if(k==='gpt-back'){back();return;}if(k==='gpt-mode'){action(v==='desktop'?'office-native-stream':'office-native:'+s.device+':'+state.app+':'+state.thread);return;}if(k==='gpt-history'||k==='gpt-history-close'){state.nativeHistory=k==='gpt-history';render();return;}if(k==='gpt-thread'){action('office-native-select:'+v);return;}if(k==='gpt-send'){send();return;}if(k==='gpt-new'){if(!editable())return;const t={id:'new-'+Date.now(),app:state.app,title:L('新会话','New session'),draft:'',messages:[]};data().threads.push(t);state.thread=t.id;rememberTopic(t.id);s.page='office-native';render();return;}if(k.startsWith('gpt-'))return;if(k==='mode'){s.mode='office';return;}return oldAction(a);};
 mobilePreviewTools=function(){return '<aside class="mobile-preview-notice office-review-note">'+L('交互演示：设备、应用窗口与会话均为样例，未连接真实电脑或 AI 服务。默认将会话 ID 传至电脑，打开对应的 VS Code / Claude / WorkBuddy。保留手机适配的直接对话界面，根据技术方案确定，技术支持后实现。手机原生对话（待继续技术调研，方案待确定）。语音为模拟转写，不录音；AI 回复为本地示例。','Interaction demo: sample devices, app windows and sessions; no live computer or AI connection. Default: send the session ID to the computer and open VS Code, Claude or WorkBuddy. Keep the phone-adapted chat design; implement direct chat if the technical solution supports it. Native phone conversations require further technical research; the approach is undecided. Voice uses simulated transcription without recording; AI replies are local examples.')+'</aside><nav class="mobile-preview-tools office-review-tools">'+button('国内','Domestic','mobile-region:domestic')+button('海外','Overseas','mobile-region:overseas')+demoControls()+'<span>'+L('演示验证码：任意6位数字','Demo code: any six digits')+'</span></nav>';};
 demoSwitcher=function(){return '';};review=function(){return '';};sourcePanel=function(){return '';};
 const oldApply=applyState;applyState=function(id){if(/game|mapping|gpt|entry|library/.test(id)){s.gameActive=false;s.mapping=false;s.virtualPad=false;if(mobileAuth.loggedIn)s.page='list';render();return;}if(id==='ai-sessions'){if(!mobileAuth.loggedIn)oldApply('list');s.page='office-ai';render();return;}return oldApply(id);};
 const oldRender=renderContent;renderContent=function(){if(state.owner!==account())reset();s.gameActive=false;s.mapping=false;s.virtualPad=false;s.gptDesktop=false;s.review=false;s.compare=false;s.mode='office';if(['gpt','home','entry','library','profile'].includes(s.page))s.page=mobileAuth.loggedIn?'list':'login';if(s.panel==='mapping')s.panel='';guardAsync();oldRender();paintSpeech();const shell=document.querySelector('.mobile-independent-shell');if(shell){const landscape=s.page==='session'&&state.landscape;s.platform=landscape?'landscape':'app';shell.classList.toggle('landscape',landscape);shell.classList.toggle('app',!landscape);shell.classList.toggle('office-session-shell',s.page==='session');}fitDesktop();requestAnimationFrame(fitDesktop);document.querySelectorAll('.fab,.review,.demo-switcher,.remote-update-review').forEach(el=>el.remove());document.querySelectorAll('[data-action^="review"],[data-action^="mode:"],[data-action^="state:"],[data-action^="mobile-preview:"]').forEach(el=>el.remove());};
 document.addEventListener('input',e=>{if(!canMessage())return;if(['office-remote-input','office-native-input'].includes(e.target.id)&&thread())thread().draft=e.target.value;if(e.target.id==='office-document')data().notes=e.target.value;});
 document.addEventListener('pointerdown',event=>{const target=event.target.closest?.('#office-native-input,.office-voice-button');if(!target){if(speech)cancelSpeech();return;}if(event.button!==0)return;startSpeech(target,event.pointerId,null);});
 document.addEventListener('pointermove',event=>{if(!speech||speech.pointer!==event.pointerId)return;const r=speech.rect;if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)cancelSpeech();});
 document.addEventListener('pointerup',event=>{if(speech?.pointer===event.pointerId)finishSpeech();});
 document.addEventListener('pointercancel',()=>cancelSpeech());
 document.addEventListener('selectstart',event=>{if(state.speechStatus==='recording'&&event.target.closest?.('#office-native-input,.office-voice-button'))event.preventDefault();});
 document.addEventListener('contextmenu',event=>{if(event.target.closest?.('#office-native-input,.office-voice-button')&&speech)event.preventDefault();});
 document.addEventListener('keydown',event=>{if(event.key==='Escape'){cancelSpeech();return;}if(event.target.matches?.('.office-voice-button')&&[' ','Enter'].includes(event.key)){event.preventDefault();event.stopImmediatePropagation();if(!event.repeat)startSpeech(event.target,null,event.key);return;}if(event.target.id==='office-native-input'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&event.keyCode!==229){event.preventDefault();event.stopImmediatePropagation();cancelSpeech();send();}},true);
 document.addEventListener('keyup',event=>{if(speech?.key===event.key){event.preventDefault();event.stopImmediatePropagation();finishSpeech();}},true);
 window.addEventListener('blur',()=>cancelSpeech());
 document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelSpeech();});
 document.addEventListener('submit',e=>{if(['office-remote-form','office-native-form'].includes(e.target.id)){e.preventDefault();send();}},true);
 // Keep single-finger pan-y native. Only two-finger gestures control the new surface scale.
 const touches=new Map();let pinch=null;
 document.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||!e.target.closest('.office-screen-viewport'))return;touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(touches.size===2){const [a,b]=[...touches.values()];pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),zoom:state.zoom};}},true);
 document.addEventListener('pointermove',e=>{if(!touches.has(e.pointerId))return;touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pinch&&touches.size===2){e.preventDefault();const [a,b]=[...touches.values()];state.zoom=Math.max(1,Math.min(2.5,pinch.zoom*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,pinch.distance)));const surface=document.querySelector('.office-screen-content');if(surface)surface.style.transform='scale('+state.zoom+')';const output=document.querySelector('.office-zoom-tools output');if(output)output.textContent=Math.round(state.zoom*100)+'%';}},true);
 for(const name of ['pointerup','pointercancel'])document.addEventListener(name,e=>{touches.delete(e.pointerId);if(touches.size<2)pinch=null;},true);
 if(params.get('state')==='ai-sessions'){if(!mobileAuth.loggedIn)oldApply('list');s.page='office-ai';}else if(/game|mapping|gpt/.test([params.get('state'),params.get('mode'),params.get('task')].join(' '))){s.page=mobileAuth.loggedIn?'list':'login';s.modal='';s.panel='';}
 document.addEventListener('toggle',event=>{const el=event.target;if(el.isConnected&&el.matches?.('details[data-office-tree]'))state.treeOpen[el.dataset.officeTree]=el.open;},true);
 window.addEventListener('resize',fitDesktop);
 window.addEventListener('remote-language-change',()=>render());
 window.RemoteOfficeMobile={state,snapshot:()=>JSON.parse(JSON.stringify({state,device:s.device,page:s.page,view:s.view})),data,open:begin,demo:applyDemo,fit:fitDesktop};
 render();
})();
